    <div className="flex flex-col rounded-lg border shadow-md p-8 m-8">
      <IssuesTable />
    </div>
  )
}

'use client'

import { useDataTableFilters } from '@bazza-ui/filters'
import {
  createTSTColumns,
  createTSTFilters,
} from '@bazza-ui/filters/tanstack-table'
import {
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  useReactTable,
} from '@tanstack/react-table'
import { useMemo, useState } from 'react'
import { Filter } from '@/registry/ui/filter'
import { tstColumnDefs } from '../lib/columns'
import { ISSUES } from '../lib/data'
import { columnsConfig } from '../lib/filters'
import { DataTable } from './data-table'

export function IssuesTable() {
  const { columns, filters, actions, strategy, entityName } =
    useDataTableFilters({
      strategy: 'client',
      data: ISSUES,
      entityName: 'Issue',
      columnsConfig,
    })

  // Step 4: Extend our TanStack Table columns with custom filter functions (and more!)
  //         using our integration hook.
  const tstColumns = useMemo(
    () =>
      createTSTColumns({
        columns: tstColumnDefs,
        configs: columns,
      }),
    [columns],
  )

  const tstFilters = useMemo(() => createTSTFilters(filters), [filters])

  // Step 5: Create our TanStack Table instance
  const [rowSelection, setRowSelection] = useState({})
  const table = useReactTable({
    data: ISSUES,
    columns: tstColumns,
    getRowId: (row) => row.id,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onRowSelectionChange: setRowSelection,
    state: {
      rowSelection,
      columnFilters: tstFilters,
      columnVisibility: {
        isUrgent: false,
      },
    },
  })

  // Step 6: Render the table!
  return (
    <div className="w-full col-span-2">
      <div className="flex items-center pb-4 gap-2">
        <Filter.Provider
          filters={filters}
          columns={columns}
          actions={actions}
          strategy={strategy}
          entityName={entityName}
        >
          <Filter.Root>
            <div className="flex md:flex-wrap gap-2 w-full flex-1">
              <Filter.Menu />
              <Filter.List>
                {({ filter, column }) => (
                  <Filter.Item filter={filter} column={column}>
                    <Filter.Subject />
                    <Filter.Operator />
                    <Filter.Value />
                    <Filter.Remove />
                  </Filter.Item>
                )}
              </Filter.List>
            </div>
            <Filter.Actions />
          </Filter.Root>
        </Filter.Provider>
      </div>
      <DataTable table={table} />
    </div>
  )
}

import { flexRender, type Table as TanStackTable } from '@tanstack/react-table'
import { Button } from '@/components/ui/button'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'

const formatNumber = (value: number) => {
  return value.toLocaleString('en-US', { maximumFractionDigits: 2 })
}

export function DataTable({ table }: { table: TanStackTable<any> }) {
  const selectedRows = formatNumber(
    table.getFilteredSelectedRowModel().rows.length,
  )
  const totalAvailableRows = formatNumber(
    table.getFilteredRowModel().rows.length,
  )
  const totalRows = formatNumber(table.getCoreRowModel().rows.length)

  return (
    <>
      <div className="rounded-md border bg-site-background">
        <Table className="rounded-md">
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id} className="bg-popover">
                {headerGroup.headers.map((header) => {
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext(),
                          )}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && 'selected'}
                  className="h-12"
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={table.getAllColumns().length}
                  className="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
      <div className="flex items-center justify-end space-x-2 py-4">
        <div className="flex-1 text-sm text-muted-foreground tabular-nums">
          {selectedRows} of {totalAvailableRows} row(s) selected.{' '}
          <span className="text-primary font-medium">
            Total row count: {totalRows}
          </span>
        </div>
        <div className="space-x-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            Previous
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            Next
          </Button>
        </div>
      </div>
    </>
  )
}

