const columnHelper = createColumnHelper<Issue>()

export const tstColumnDefs = [
  columnHelper.display({
    id: 'select',
    header: ({ table }) => (
      <Checkbox
        checked={
          table.getIsAllPageRowsSelected() ||
          (table.getIsSomePageRowsSelected() && 'indeterminate')
        }
        onCheckedChange={(value) => table.toggleAllRowsSelected(!!value)}
        aria-label="Select all"
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => row.toggleSelected(!!value)}
        aria-label="Select row"
      />
    ),
    enableSorting: false,
    enableHiding: false,
    enableColumnFilter: false,
  }),
  columnHelper.accessor((row) => row.status.id, {
    id: 'status',
    header: 'Status',
    enableColumnFilter: true,
    cell: ({ row }) => {
      const { status } = row.original
      const StatusIcon = status.icon

      return (
        <div className="flex items-center gap-2">
          <StatusIcon className="size-4" />
          <span>{status.name}</span>
        </div>
      )
    },
  }),
  columnHelper.accessor((row) => row.title, {
    id: 'title',
    header: 'Title',
    enableColumnFilter: true,
    cell: ({ row }) => (
      <div className="flex items-center gap-2">
        <span>{row.getValue('title')}</span>
        {row.original.isUrgent && (
          <Tooltip>
            <TooltipTrigger asChild>
              <CircleAlertIcon className="size-5 fill-red-600 stroke-[2.5px] stroke-white dark:stroke-black" />
            </TooltipTrigger>
            <TooltipContent>Urgent issue</TooltipContent>
          </Tooltip>
        )}
      </div>
    ),
  }),
  columnHelper.accessor((row) => row.isUrgent, {
    id: 'isUrgent',
    header: 'Urgent',
    enableColumnFilter: true,
    cell: ({ row }) => {
      const isUrgent = row.getValue<boolean>('isUrgent')

      if (!isUrgent) {
        return null
      }

      return (
        <div className="flex items-center gap-2 rounded-md">
          <CircleAlertIcon className="" />
          <span>Urgent</span>
        </div>
      )
    },
  }),
  columnHelper.accessor((row) => row.assignee?.id, {
    id: 'assignee',
    header: 'Assignee',
    enableColumnFilter: true,
    cell: ({ row }) => {
      const user = row.original.assignee

      if (!user) {
        return <CircleDashedIcon className="size-5 text-border" />
      }

      const initials = user.name
        .split(' ')
        .map((x) => x[0])
        .join('')
        .toUpperCase()

      return (
        <Avatar className="size-5">
          <AvatarImage src={user.picture} />
          <AvatarFallback>{initials}</AvatarFallback>
        </Avatar>
      )
    },
  }),
  columnHelper.accessor((row) => row.estimatedHours, {
    id: 'estimatedHours',
    header: 'Estimated Hours',
    enableColumnFilter: true,
    cell: ({ row }) => {
      const estimatedHours = row.getValue<number>('estimatedHours')

      if (!estimatedHours) {
        return null
      }

      return (
        <span>
          <span className="tabular-nums tracking-tighter">
            {estimatedHours}
          </span>
          <span className="text-muted-foreground ml-0.5">h</span>
        </span>
      )
    },
  }),
  columnHelper.accessor((row) => row.startDate, {
    id: 'startDate',
    header: 'Start Date',
    enableColumnFilter: true,
    cell: ({ row }) => {
      const startDate = row.getValue<Issue['startDate']>('startDate')

      if (!startDate) {
        return null
      }

      const formatted = format(startDate, 'MMM dd')

      return <span>{formatted}</span>
    },
  }),
  columnHelper.accessor((row) => row.endDate, {
    id: 'endDate',
    header: 'End Date',
    cell: ({ row }) => {
      const endDate = row.getValue<Issue['endDate']>('endDate')

      if (!endDate) {
        return null
      }

      const formatted = format(endDate, 'MMM dd')

      return <span>{formatted}</span>
    },
  }),
  columnHelper.accessor((row) => row.labels, {
    id: 'labels',
    header: 'Labels',
    enableColumnFilter: true,
    cell: ({ row }) => {
      const labels = row.original.labels

      if (!labels) return null

      return (
        <div className="flex gap-1">
          {labels.map((l) => (
            <div
              key={l.id}
              className={cn(
                'flex items-center gap-1 py-1 px-2 rounded-md text-[12px] shadow-xs text-white font-medium border',
                LABEL_STYLES_MAP[l.color as TW_COLOR],
              )}
            >
              {l.name}
            </div>
          ))}
        </div>
      )
    },
  }),
